export default class Youtube {
  constructor(element) {
    this.youtube = element;

    this.videoContainer = this.youtube.querySelector('.js-video');
    this.poster = this.youtube.querySelector('.js-poster');
    this.videoId = this.youtube.dataset.videoId;
    this.autoplay = this.poster ? 1 : 0;
    this.playerReady = false;
    this.noControls = 1;

    Youtube.instances.push(this);
    // console.log(Youtube.instances);

    if (this.videoId) {
      Youtube.loadScript();
    } else {
      console.error('vous devez spécifier un id');
    }
  }

  static loadScript() {
    if (!Youtube.scriotIsLoading) {
      Youtube.scriptIsLoading = true;
      const script = document.createElement('script');
      script.src = 'https://www.youtube.com/iframe_api';
      document.body.appendChild(script);
    }
  }

  init() {
    console.log('YT est prêt');

    this.initPlayer = this.initPlayer.bind(this);

    if (this.poster) {
      this.youtube.addEventListener('click', this.initPlayer);
    } else {
      this.initPlayer();
    }

    this.setOptions();
  }

  setOptions() {
    if ('noControls' in this.youtube.dataset) {
      // console.log('no controls');
      this.noControls = 0;
    }
  }

  initPlayer(e) {
    if (e) {
      this.youtube.removeEventListener('click', this.initPlayer);
    }

    this.player = new YT.Player(this.videoContainer, {
      videoId: this.videoId,
      height: '100%',
      width: '100%',
      playerVars: {
        rel: 0,
        autoplay: this.autoplay,
        controls: this.noControls,
      },
      events: {
        onReady: () => {
          this.playerReady = true;
          const observer = new IntersectionObserver(this.watch.bind(this), {
            rootMargin: '0px 0px 0px 0px',
          });

          observer.observe(this.youtube);
        },
        onStateChange: (event) => {
          if (event.data == YT.PlayerState.PLAYING) {
            //pause tous les vidéos SAUF celui qui joue
            Youtube.pauseAll(this);
          } else if (event.data == YT.PlayerState.ENDED) {
            // console.log('ended');
            this.player.seekTo(0);
            this.player.pauseVideo();
          }
        },
      },
    });
  }

  watch(entries) {
    if (this.playerReady && !entries[0].isIntersecting) {
      this.player.pauseVideo();
    }
  }

  static initAll() {
    document.documentElement.classList.add('is-video-ready');

    for (let i = 0; i < Youtube.instances.length; i++) {
      const instance = Youtube.instances[i];
      instance.init();
    }
  }

  static pauseAll(currentInstance) {
    for (let i = 0; i < Youtube.instances.length; i++) {
      const instance = Youtube.instances[i];
      if (instance.playerReady && instance !== currentInstance) {
        instance.player.pauseVideo();
      }
    }
  }
}

Youtube.instances = [];
window.onYouTubeIframeAPIReady = Youtube.initAll;
